/* Complete interactive screen set. All service outcomes remain local simulations. */
Object.assign(state,{ui:{languages:['Italiano'],intention:'Conoscersi con calma',common:1,hideOnline:false,hideLastSeen:false,discoverable:true,photoConsent:false,alertDays:['Martedì','Giovedì'],alertTime:'21:00',alertTopics:['Cinema'],alertsEnabled:false,saved:[],nextId:1,verifiedStep:0,pendingFeature:null}});
const featureRoutes={
 'Scegli la città':'locationSettings','Decidi la distanza':'locationSettings','Anteprima del profilo':'photoPreview','Filtri di affinità avanzati':'affinity','Modalità discreta':'discretion','Anteprima delle chat':'chatPreview','Chiamate illimitate':'unlimited','Avvisi personalizzati':'alerts','Preferenze salvate':'savedSearches'
};
const premiumRowBeforeScreens=premiumRow;
premiumRow=function(symbol,title,copy){const route=featureRoutes[title];if(!route)return premiumRowBeforeScreens(symbol,title,copy);return `<li class="premium-row feature-row"><button class="premium-feature" onclick="openFeature('${route}')"><span class="premium-medallion" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6">${premiumSymbols[symbol]}</svg></span><span class="feature-copy"><strong>${title}</strong><span>${copy}</span></span><span class="feature-arrow" aria-hidden="true">›</span></button></li>`};
const premiumPanelBeforeScreens=openPremium;
openPremium=function(){premiumPanelBeforeScreens();const headings=document.querySelectorAll('.premium-group h3');if(headings[0])headings[0].textContent='Scegli dove incontrarti';if(headings[1])headings[1].textContent='Tutti i vantaggi Premium';const note=document.querySelector('.premium-proposed');if(note)note.textContent='Apri un vantaggio per esplorarlo. Servizi e risultati sono simulati nel mockup.';const disclaimer=document.querySelector('.premium-note');if(disclaimer)disclaimer.textContent='6€ al mese. Il percorso di abbonamento è dimostrativo: nessun addebito.';};
function screenGo(view){closePanel();go(view)}
function openFeature(view){state.ui.pendingFeature=view;if(!state.premium){openPremium();toast('Attiva Premium nella demo per provare questo vantaggio');return}screenGo(view)}
togglePremiumDemo=function(){screenGo(state.premium?'cancelPlan':'checkout')};
function screenCard(content){return `<div class="screen-paper">${content}</div>`}
function screenLink(view,title,desc,kind='settings'){return `<button class="screen-link" onclick="${kind==='premium'?`openFeature('${view}')`:`screenGo('${view}')`}"><span><strong>${title}</strong><small>${desc}</small></span>${icon('chevron')}</button>`}
function screenHeader(title,subtitle='',backTo='settings'){return `${back(backTo)}<p class="eyebrow">${state.premium?'Voemi Premium':'Il tuo spazio'}</p><h1 tabindex="-1">${title}</h1>${subtitle?`<p class="lead">${subtitle}</p>`:''}`}
function screenToggle(key,title,copy){return `<label class="screen-toggle"><span><strong>${title}</strong><small>${copy}</small></span><input type="checkbox" role="switch" ${state.ui[key]?'checked':''} onchange="state.ui.${key}=this.checked;toast('Preferenza aggiornata nella demo')"></label>`}
function choices(key,values){return `<div class="screen-chips">${values.map(v=>`<button type="button" class="interest ${state.ui[key].includes(v)?'selected':''}" aria-pressed="${state.ui[key].includes(v)}" onclick="toggleScreenChoice('${key}','${v}')">${v}</button>`).join('')}</div>`}
function toggleScreenChoice(key,value){const list=state.ui[key];state.ui[key]=list.includes(value)?list.filter(v=>v!==value):[...list,value];render()}
const featureViews=new Set(Object.values(featureRoutes));
const screens={
 discoveryPaused:()=>`${screenHeader('Ti sei preso una pausa','La disponibilità per nuovi incontri è disattivata.','discretion')}${screenCard('<p>Le tue chat restano aperte. Riattiva la disponibilità quando vuoi conoscere qualcuno di nuovo.</p>')}<button class="primary" onclick="state.ui.discoverable=true;startSearch()">Torna disponibile e cerca</button>`,
 settings:()=>`${screenHeader('Il tuo spazio','Preferenze, abbonamento e sicurezza.','profile')}${screenLink('subscription','Il tuo piano',state.premium?'Premium · 6€ al mese':'Base · scopri Premium')}${screenLink('photoPreview','Anteprima del profilo','Foto e consenso della persona','premium')}${screenLink('chatPreview','Anteprima delle chat','Ascolta senza inviare conferme','premium')}${screenLink('unlimited','Chiamate illimitate','Come funzionano i primi tre minuti','premium')}${screenLink('affinity','Affinità','Lingue, intenzioni e interessi comuni','premium')}${screenLink('discretion','Modalità discreta','Stato online e disponibilità','premium')}${screenLink('alerts','Avvisi personalizzati','Temi, giorni e orari','premium')}${screenLink('savedSearches','Preferenze salvate','Le tue combinazioni di filtri','premium')}${screenLink('privacySettings','Privacy e visibilità','Consenso foto e informazioni condivise')}${screenLink('blockedProfiles','Profili bloccati','Gestisci le persone che hai bloccato')}${screenLink('account','Account e verifica',state.verified?'Verifica demo completata':'Completa il percorso dimostrativo')}${screenLink('demoIndex','Esplora il mockup','Tutti i percorsi e gli stati disponibili')}`,
 subscription:()=>`${screenHeader('Il tuo piano',state.premium?'Più spazio alle conversazioni.':'Prima la voce, poi il profilo.')}${screenCard(`<span class="screen-plan">${state.premium?'PREMIUM':'BASE'}</span><h2>${state.premium?'6€ <small>al mese</small>':'Il piacere di iniziare'}</h2><p>${state.premium?'Città, distanza e tutte le schermate Premium sono sbloccate nella demo.':'Scegli un tema e conosci una persona attraverso la voce.'}</p><p class="microcopy">Nessun pagamento reale. Lo stato si azzera ricaricando la pagina.</p>`)}${state.premium?`${screenLink('receipt','Riepilogo del piano','Quota mensile e stato della simulazione')}<button class="secondary" onclick="screenGo('cancelPlan')">Gestisci il piano</button>`:'<button class="primary" onclick="openPremium()">Scopri Voemi Premium</button>'}`,
 checkout:()=>`${screenHeader('Il tuo abbonamento','Un passo in più verso la prossima conversazione.','subscription')}${screenCard('<span class="screen-plan">VOEMI PREMIUM</span><h2>6€ <small>al mese</small></h2><p>Città e distanza personalizzate, chiamate illimitate e più controllo sulla tua esperienza.</p><hr><p><strong>Totale mensile: 6€</strong></p><p>Pagamento e rinnovo non vengono eseguiti in questo mockup.</p>')}<div class="screen-demo-note">Modalità dimostrativa: non inserire carte o dati di pagamento.</div><button class="primary" onclick="simulatePayment(false)">Conferma nella demo</button><button class="text-button" onclick="simulatePayment(true)">Prova un pagamento non riuscito</button>`,
 paymentPending:()=>`${screenHeader('Un momento…','Stiamo preparando il tuo piano nella simulazione.','checkout')}<div class="screen-loader" aria-hidden="true"></div><p role="status">Attivazione in corso</p><button class="secondary" onclick="screenGo('checkout')">Annulla</button>`,
 paymentFailed:()=>`${screenHeader('Non è andata a buon fine','Nessun addebito è stato effettuato. Puoi riprovare.','checkout')}${screenCard('<h2>Pagamento non riuscito · demo</h2><p>Questo stato simula un errore del servizio di pagamento.</p>')}<button class="primary" onclick="simulatePayment(false)">Riprova nella demo</button><button class="text-button" onclick="screenGo('subscription')">Torna al tuo piano</button>`,
 premiumSuccess:()=>`${screenHeader('Benvenuto in Premium','Il tuo piano è attivo nella demo.','subscription')}<div class="screen-success">${icon('check')}</div>${screenCard('<h2>Le tue preferenze, più spazio</h2><p>Ora puoi impostare città e distanza e provare tutte le schermate Premium.</p>')}<button class="primary" onclick="screenGo(state.ui.pendingFeature||'locationSettings')">Personalizza la tua esperienza</button><button class="text-button" onclick="screenGo('home')">Esplora le stanze</button>`,
 receipt:()=>`${screenHeader('Riepilogo del piano','Una panoramica semplice, sempre a portata di mano.','subscription')}${screenCard(`<dl class="screen-summary"><div><dt>Piano</dt><dd>${state.premium?'Voemi Premium':'Base'}</dd></div><div><dt>Quota proposta</dt><dd>6€ / mese</dd></div><div><dt>Addebiti effettuati</dt><dd>0€</dd></div><div><dt>Rinnovo reale</dt><dd>Non attivo</dd></div></dl><p class="microcopy">Riepilogo dimostrativo, non una ricevuta fiscale.</p>`)}`,
 cancelPlan:()=>`${screenHeader('Vuoi tornare al piano Base?','Le tue connessioni e i messaggi della sessione restano disponibili.','subscription')}${screenCard('<h2>Cosa cambia</h2><p>Città, raggio e strumenti Premium tornano bloccati. Nel mockup il cambio è immediato e non coinvolge pagamenti.</p>')}<button class="primary" onclick="screenGo('subscription')">Mantieni Premium</button><button class="secondary" onclick="cancelPremium()">Torna a Base nella demo</button>`,
 planCancelled:()=>`${screenHeader('Sei tornato al piano Base','Puoi continuare a conoscere persone attraverso la voce.','subscription')}<div class="screen-success">${icon('check')}</div><button class="primary" onclick="screenGo('home')">Torna alle stanze</button>`,
 locationSettings:()=>`${screenHeader('Dove vuoi conoscere qualcuno?','Scegli una città e la distanza che preferisci.')}<form onsubmit="saveLocation(event)"><label for="premium-city">Città</label><input id="premium-city" required maxlength="40" value="${esc(state.city)}"><label for="premium-radius">Raggio di ricerca</label><select id="premium-radius">${[5,10,25,50,100].map(n=>`<option value="${n}" ${n===state.radius?'selected':''}>${n} km</option>`).join('')}</select><p class="microcopy">Non usiamo il GPS. I risultati disponibili del pilota sono simulati a Roma.</p><button class="primary" type="submit">Salva posizione di ricerca</button></form>${screenLink('savedSearches','Salva una ricerca','Conserva questa combinazione di filtri','premium')}`,
 affinity:()=>`${screenHeader('Le vostre affinità','Piccoli punti in comune da cui iniziare.')}${screenCard(`<h2>Lingue della conversazione</h2>${choices('languages',['Italiano','Inglese','Spagnolo','Francese'])}`)}<form onsubmit="saveAffinity(event)"><label for="dating-intent">Cosa cerchi?</label><select id="dating-intent" onchange="state.ui.intention=this.value">${['Conoscersi con calma','Una relazione','Nuove conoscenze'].map(v=>`<option ${state.ui.intention===v?'selected':''}>${v}</option>`).join('')}</select><label for="common-count">Interessi in comune</label><select id="common-count" onchange="state.ui.common=Number(this.value)">${[1,2,3].map(n=>`<option value="${n}" ${n===state.ui.common?'selected':''}>Almeno ${n}</option>`).join('')}</select><p class="microcopy">Preferenze salvate nella sessione; il matching resta simulato.</p><button class="primary">Salva affinità</button></form>`,
 discretion:()=>`${screenHeader('Decidi quando esserci','Più riservatezza, senza rinunciare alle tue connessioni.')}${screenCard(`${screenToggle('hideOnline','Nascondi lo stato online','Le altre persone non vedranno quando sei connesso.')}${screenToggle('hideLastSeen','Nascondi l’ultimo accesso','Non mostrare quando hai usato Voemi l’ultima volta.')}${screenToggle('discoverable','Disponibile per nuovi incontri','Se disattivato, non partecipi alle nuove ricerche. Le chat restano disponibili.')}`)}<p class="microcopy">Questa schermata simula le preferenze di visibilità: nessun dato viene trasmesso.</p><button class="primary" onclick="screenGo('settings')">Fatto</button>`,
 privacySettings:()=>`${screenHeader('La tua privacy','La voce viene prima. Il controllo resta tuo.')}${screenCard(`${screenToggle('photoConsent','Consenti l’anteprima della foto','Le persone Premium possono vedere la tua foto prima del match solo se lo consenti. Disattivato per impostazione iniziale.')}<p>Il profilo completo e la chat si sbloccano soltanto dopo un sì reciproco.</p><p>Il numero di telefono non viene mostrato.</p>`)}${screenLink('blockedProfiles','Persone bloccate','Rivedi o rimuovi un blocco')}<button class="secondary" onclick="privacyPanel()">Come funziona la privacy</button>`,
 alerts:()=>`${screenHeader('Il momento giusto per te','Scegli di cosa parlare e quando tornare.')}${screenCard(`${screenToggle('alertsEnabled','Avvisi attivi','Preferenza della demo, senza notifiche reali.')}<h2>Giorni</h2>${choices('alertDays',['Lunedì','Martedì','Mercoledì','Giovedì','Venerdì','Sabato','Domenica'])}<h2>Argomenti</h2>${choices('alertTopics',categories.map(c=>c.name))}`)}<form onsubmit="saveAlerts(event)"><label for="alert-time">Orario preferito · Roma</label><input id="alert-time" type="time" onchange="state.ui.alertTime=this.value" required value="${state.ui.alertTime}"><button class="primary">Salva avvisi</button></form>`,
 alertsSaved:()=>`${screenHeader('Avvisi salvati','Il tuo prossimo momento per una conversazione.','alerts')}${screenCard(`<h2>${esc(state.ui.alertDays.join(', '))}</h2><p>Alle ${esc(state.ui.alertTime)} · orario di Roma</p><p>${esc(state.ui.alertTopics.join(' · '))}</p><p class="microcopy">Nessuna notifica viene inviata dal mockup.</p>`)}<button class="primary" onclick="screenGo('home')">Esplora le stanze</button>`,
 savedSearches:()=>`${screenHeader('Le tue ricerche preferite','Ritrova città, distanza, età e interessi senza ricominciare.')}${state.ui.saved.length?state.ui.saved.map(s=>screenCard(`<h2>${esc(s.name)}</h2><p>${esc(s.city)} · ${s.radius} km · ${s.min}–${s.max} anni</p><p>${esc(s.preference)} · ${esc(s.interests.join(', '))}</p><div class="screen-actions"><button class="primary" onclick="applySavedSearch(${s.id})">Usa ricerca</button><button class="text-button" onclick="deleteSavedSearch(${s.id})">Elimina</button></div>`)).join(''):screenCard('<h2>La tua prima ricerca preferita</h2><p>Salva i filtri che usi più spesso e ritrovali qui.</p>')}<form onsubmit="saveSearch(event)"><label for="search-name">Nome della ricerca</label><input id="search-name" required maxlength="45" placeholder="Es. Vicino a casa"><p class="microcopy">Salverai i filtri attuali: ${esc(state.city)}, ${state.radius} km, ${state.min}–${state.max} anni.</p><button class="primary">Salva i filtri attuali</button></form>`,
 chatPreview:()=>`${screenHeader('Ascolta con i tuoi tempi','L’anteprima non invia conferme di ascolto.','messages')}${state.matched?screenCard(`<h2>${personName()}</h2>${state.messages.filter(m=>!m.mine).map(m=>voiceBubble(m,state.messages.indexOf(m),true)).join('')||'<p>Non ci sono ancora note vocali ricevute.</p>'}<button class="primary" onclick="screenGo('chat')">Apri la conversazione</button>`):screenCard('<h2>Qui compariranno le tue note vocali</h2><p>Prima una chiamata e un sì reciproco. Poi potrete risentirvi.</p>')}`,

 photoPreview:()=>`${screenHeader('Prima uno sguardo','Solo quando l’altra persona ha consentito l’anteprima.')}${screenCard(`<div class="screen-photo">${personAvatar(!state.demoPhotoConsent)}</div><h2>${personName()}, ${personAge()}</h2><p>${state.demoPhotoConsent?'Questo profilo dimostrativo consente l’anteprima della foto. Il profilo completo e la chat richiedono un match reciproco.':'Questa persona non ha consentito l’anteprima. La sua scelta vale anche per gli utenti Premium.'}</p><button class="secondary" onclick="state.demoPhotoConsent=!state.demoPhotoConsent;render()">Prova ${state.demoPhotoConsent?'consenso negato':'consenso concesso'} · demo</button>`)}<button class="primary" onclick="screenGo('ready')">Conosci questa voce</button>`,
 unlimited:()=>`${screenHeader('Una conversazione dopo l’altra','Con Premium non c’è un limite giornaliero di chiamate.')}${screenCard('<h2>Il tempo di conoscervi</h2><p>Ogni primo incontro comincia con tre minuti. Poi potete continuare, se lo volete entrambi.</p><p>Le chiamate dipendono dalle persone compatibili disponibili. Nessun collegamento audio reale viene avviato nel mockup.</p>')}<button class="primary" onclick="screenGo('home')">Scegli una stanza</button>`,
 blockedProfiles:()=>`${screenHeader('Persone bloccate','Un confine che puoi gestire in ogni momento.')}${state.blocked?screenCard(`<h2>${personName()}</h2><p>Non potete contattarvi o incontrarvi nelle ricerche della demo.</p><button class="secondary" onclick="state.blocked=false;render();toast('Blocco rimosso nella demo')">Sblocca</button>`):screenCard('<h2>Nessun profilo bloccato</h2><p>Puoi bloccare una persona dalla chiamata, dalla chat o dal suo profilo.</p>')}`,
 account:()=>`${screenHeader('Il tuo account','Accesso e verifica, un passo alla volta.')}${screenCard(`<h2>${esc(state.name)}</h2><p>${state.verified?'Percorso di verifica completato nella demo.':'Il tuo account dimostrativo deve ancora completare la verifica.'}</p>`)}${screenLink('verifyContact','Verifica il tuo account','Recapito, codice e identità · simulazione')}${screenLink('welcome','Accesso a Voemi','Esplora il percorso di accesso')}<p class="microcopy">Non vengono creati account reali o raccolti documenti.</p>`,
 welcome:()=>`${screenHeader('Prima la voce, poi il profilo','Due persone. Una conversazione. Un argomento in comune.','account')}<div class="screen-brand">${drivePicture('Voemi_Logo_logo.png')}</div><button class="primary" onclick="screenGo('login')">Accedi</button><button class="secondary" onclick="startOnboarding()">Crea il tuo profilo · demo</button>`,
 login:()=>`${screenHeader('Bentornato','Prova un accesso senza password.','welcome')}${screenCard('<label for="demo-email">Indirizzo dimostrativo</label><input id="demo-email" value="voce@example.com" readonly><p class="microcopy">Usiamo un recapito fittizio. Nessuna email verrà inviata.</p>')}<button class="primary" onclick="state.ui.verificationMode=false;screenGo('verifyCode')">Continua nella demo</button>`,
 verifyContact:()=>`${screenHeader('Verifica il recapito','Il primo passo per un account affidabile.','account')}${screenCard('<p class="screen-plan">1 DI 3 · RECAPITO</p><label for="verify-email">Email dimostrativa</label><input id="verify-email" value="voce@example.com" readonly><p>Nessun recapito reale viene raccolto o contattato.</p>')}<button class="primary" onclick="state.ui.verificationMode=true;screenGo('verifyCode')">Invia codice · simulazione</button>`,
 verifyCode:()=>`${screenHeader('Inserisci il codice','Nella demo usa 123456.',state.ui.verificationMode?'verifyContact':'login')}<form onsubmit="checkDemoCode(event)"><label for="demo-code">Codice a sei cifre</label><input id="demo-code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required aria-describedby="code-error"><p id="code-error" class="field-error" role="alert"></p><button class="primary">Conferma codice</button></form><button class="text-button" onclick="toast('Il codice dimostrativo è sempre 123456')">Invia di nuovo · demo</button>`,
 verifyIdentity:()=>`${screenHeader('Conferma che sei tu','Una verifica pensata per persone reali.','verifyContact')}${screenCard('<p class="screen-plan">3 DI 3 · IDENTITÀ</p><div class="screen-success">'+icon('user')+'</div><h2>Un breve controllo del volto</h2><p>Nel prodotto reale seguirai le indicazioni del servizio di verifica. Qui non apriamo la fotocamera e non raccogliamo immagini o documenti.</p>')}<button class="primary" onclick="state.verified=true;screenGo('verifiedDone')">Simula verifica completata</button>`,
 verifiedDone:()=>`${screenHeader('Tutto pronto','Hai completato il percorso dimostrativo.','account')}<div class="screen-success">${icon('check')}</div><p class="lead">Questo risultato non certifica l’identità di una persona reale.</p><button class="primary" onclick="screenGo('home')">Trova una conversazione</button>`,
 microphoneSetup:()=>`${screenHeader('Un momento per la tua voce','Trova un posto tranquillo prima di cominciare.','ready')}${screenCard('<h2>Microfono e audio</h2><p>Nell’app reale potrai autorizzare il microfono e controllare l’audio. In questa demo non viene richiesto alcun permesso.</p>')}<button class="primary" onclick="startSearch()">Continua senza audio · demo</button><button class="text-button" onclick="screenGo('microphoneDenied')">Prova microfono non disponibile</button>`,
 microphoneDenied:()=>`${screenHeader('Non riusciamo a sentirti','Il microfono non è disponibile.','microphoneSetup')}${screenCard('<p>Nel prodotto reale controlla i permessi del microfono e che non sia occupato da un’altra app.</p><p>Questo è uno stato di errore simulato.</p>')}<button class="primary" onclick="screenGo('microphoneSetup')">Riprova</button><button class="text-button" onclick="screenGo('home')">Torna alle stanze</button>`,
 callInterrupted:()=>`${screenHeader('La chiamata si è interrotta','Può capitare. Scegli come continuare.','home')}${screenCard(`<h2>La voce di ${personName()} non è più connessa</h2><p>Il mockup simula una perdita di connessione. Nessun audio reale è stato interrotto.</p>`)}<button class="primary" onclick="startSearch()">Cerca di nuovo</button><button class="secondary" onclick="go('feedback')">Scegli se risentirvi</button>`,
 noMatch:()=>`${screenHeader('Questa volta le strade si dividono','Un incontro può essere piacevole anche senza un seguito.','home')}${screenCard('<h2>La tua scelta resta privata</h2><p>La chat e il profilo completo non vengono sbloccati senza un sì reciproco.</p>')}<button class="primary" onclick="screenGo('home')">Trova una nuova conversazione</button>`,
 reportDone:()=>`${screenHeader('Simulazione completata','Il profilo è stato bloccato nella sessione.','home')}${screenCard('<h2>La tua tranquillità conta</h2><p>Nel prodotto reale una segnalazione arriverebbe al servizio di moderazione. Da questo mockup non è stato inviato nulla.</p>')}<button class="primary" onclick="screenGo('home')">Torna alle stanze</button>${screenLink('blockedProfiles','Gestisci il blocco','Rivedi i profili bloccati')}`,
 demoIndex:()=>`${screenHeader('Esplora il mockup','Prova i percorsi e gli stati senza servizi reali.','settings')}${screenLink('welcome','Accesso e registrazione','Ingresso, codice e onboarding')}${screenLink('verifyContact','Verifica account','Recapito, codice e identità')}${screenLink('subscription','Abbonamento','Riepilogo, acquisto simulato, errore e annullamento')}${screenLink('settings','Preferenze Premium','Posizione, affinità, discrezione, avvisi e ricerche')}${screenLink('microphoneSetup','Preparazione chiamata','Microfono e permessi negati')}${screenLink('callInterrupted','Chiamata interrotta','Recupero della conversazione')}${screenLink('noMatch','Scelta non reciproca','Nessuna chat sbloccata')}<button class="secondary" onclick="loadDemoConversation()">Carica una connessione e una nota vocale di esempio</button><p class="microcopy">L’esempio sostituisce la conversazione della sessione. Nessun messaggio viene inviato a persone reali.</p>`
};
function simulatePayment(fail){screenGo('paymentPending');later(()=>{if(fail){go('paymentFailed');return}if(!state.premium)state.freeCity=state.city;state.premium=true;go('premiumSuccess')},1000)}
function cancelPremium(){state.premium=false;state.city=state.freeCity;state.radius=25;state.ui.discoverable=true;screenGo('planCancelled')}
function saveLocation(e){e.preventDefault();if(!state.premium)return openPremium();const city=document.getElementById('premium-city').value.trim();if(!city)return;state.city=city;state.radius=Number(document.getElementById('premium-radius').value);toast('Posizione di ricerca salvata');screenGo('settings')}
function saveAffinity(e){e.preventDefault();if(!state.premium)return openPremium();if(!state.ui.languages.length){toast('Scegli almeno una lingua');return}state.ui.intention=document.getElementById('dating-intent').value;state.ui.common=Number(document.getElementById('common-count').value);toast('Affinità salvate nella demo');screenGo('settings')}
function saveAlerts(e){e.preventDefault();if(!state.premium)return openPremium();if(!state.ui.alertDays.length||!state.ui.alertTopics.length){toast('Scegli almeno un giorno e un argomento');return}state.ui.alertTime=document.getElementById('alert-time').value;state.ui.alertsEnabled=true;screenGo('alertsSaved')}
function saveSearch(e){e.preventDefault();if(!state.premium)return openPremium();const name=document.getElementById('search-name').value.trim();if(!name)return;state.ui.saved.push({id:state.ui.nextId++,name,city:state.city,radius:state.radius,min:state.min,max:state.max,preference:state.preference,interests:[...state.interests]});render();toast('Ricerca salvata')}
function applySavedSearch(id){if(!state.premium)return openPremium();const s=state.ui.saved.find(x=>x.id===id);if(!s)return;Object.assign(state,{city:s.city,radius:s.radius,min:s.min,max:s.max,preference:s.preference,interests:[...s.interests]});screenGo('home');toast('Ricerca applicata')}
function deleteSavedSearch(id){state.ui.saved=state.ui.saved.filter(s=>s.id!==id);render();toast('Ricerca eliminata')}
function checkDemoCode(e){e.preventDefault();if(document.getElementById('demo-code').value!=='123456'){document.getElementById('code-error').textContent='Codice non corretto. Nella demo usa 123456.';return}screenGo(state.ui.verificationMode?'verifyIdentity':'home')}
function loadDemoConversation(){state.matched=true;state.blocked=false;state.messages=[{type:'audio',duration:18,mine:false,read:false,time:'Adesso'}];screenGo('messages')}
const searchBeforeScreens=startSearch;
startSearch=function(){if(state.premium&&!state.ui.discoverable){screenGo('discoveryPaused');return}searchBeforeScreens()};
confirmReady=function(){state.promptIndex=0;screenGo('microphoneSetup')};
verificationPanel=function(){screenGo('verifyContact')};
submitReport=function(e){e.preventDefault();state.blocked=true;state.matched=false;state.messages=[];screenGo('reportDone')};
const privacyBeforeScreens=privacyPanel;
privacyPanel=function(){privacyBeforeScreens();const p=document.querySelector('.trust-list p');if(p)p.innerHTML='<strong>Prima, solo la voce</strong>Nome, età, zona e interessi sono visibili. Il profilo completo e la chat richiedono una scelta reciproca. L’anteprima della foto Premium è possibile solo con il consenso della persona.';};
const optionsBeforeScreens=callOptions;
callOptions=function(){optionsBeforeScreens();document.getElementById('filter-dialog').insertAdjacentHTML('beforeend','<button class="text-button" onclick="screenGo(\'callInterrupted\')">Prova interruzione · demo</button>')};
const goBeforeScreens=go;
go=function(view){goBeforeScreens(view);if(screens[view])app.querySelector('h1')?.focus({preventScroll:true})};
const navBeforeScreens=nav;
nav=function(){const view=state.view;if(screens[view]){state.view=['chatPreview','photoPreview'].includes(view)?'messages':'profile';navBeforeScreens();state.view=view;document.body.classList.remove('no-bottom-nav')}else navBeforeScreens()};
const materialsBeforeScreens=applyMaterials;
applyMaterials=function(){materialsBeforeScreens();document.querySelectorAll('.screen-paper,.screen-link').forEach(el=>{materialObserver.observe(el);paperLayer(el)});document.querySelectorAll('input[type=checkbox]').forEach(input=>{const wrapper=input.closest('.png-input-shell');if(wrapper)wrapper.replaceWith(input)});};
function unreadLabel(){const n=state.messages.filter(m=>!m.mine&&!m.read).length;return `${n} ${n===1?'nota da ascoltare':'note da ascoltare'}`}
const renderBeforeScreens=render;
render=function(){
 if(screens[state.view]){
  const locked=featureViews.has(state.view)&&!state.premium;
  app.innerHTML=`<section class="screen-view page-enter">${locked?screenHeader('Questo spazio è Premium','Attiva il piano nella demo per personalizzare la tua esperienza.')+'<button class="primary" onclick="openPremium()">Scopri Premium</button>':screens[state.view]()}<p class="screen-session-note">Mockup interattivo · dati conservati solo nella sessione</p></section>`;
  document.body.dataset.view=state.view;nav();applyMaterials();return;
 }
 renderBeforeScreens();
 if(state.view==='profile')app.insertAdjacentHTML('beforeend',`<section class="screen-profile-menu">${screenLink('settings','Impostazioni e Premium','Gestisci il tuo spazio')}${screenLink('demoIndex','Esplora tutte le schermate','Percorsi e stati del mockup')}</section>`);
 if(state.view==='found')app.querySelector('.flow-actions').insertAdjacentHTML('beforeend','<button class="text-button" onclick="openFeature(\'photoPreview\')">Anteprima foto · Premium</button>');
 if(state.view==='waiting')app.querySelector('.flow-actions').insertAdjacentHTML('beforeend','<button class="text-button" onclick="state.matched=false;screenGo(\'noMatch\')">Prova scelta non reciproca · demo</button>');
 if(state.view==='messages'&&state.matched)app.querySelector('section').insertAdjacentHTML('beforeend',`<button class="secondary" onclick="openFeature('chatPreview')">${unreadLabel()} · Anteprima Premium</button>`);
 if(state.view==='chat')app.querySelector('.privacy-copy').insertAdjacentHTML('beforebegin','<p class="microcopy">Le note vocali sono segnate come ascoltate solo quando le riproduci.</p>');
 applyMaterials();
};
render();
